   dwLowInvVA;extern INT32S   dwLowBatWatt;extern INT16U   wSwitchToLineEn;extern INT16U wParaMode;extern INT16U   wIDAutoGenerateStep;extern INT16U   wIDHighTemp;extern INT16U   wIDLowTemp;extern INT16S   wInvVoltErrorSum;extern INT16S   wOPShareCurrCntlErr_Filter;extern INT16S   wOPShareCurrCntlErr_1;extern INT16U   wOPWattBatPercent;extern INT16U   wOPVABatPercent;extern INT16U   wOPPowerBatPercent;extern INT16U   wFANPWMTempNew;extern INT16U   wInvOver55CBack45;extern INT16U   wInvWattPercent;extern INT16U   wInvVAPercent;extern INT16U wOPWattPercent;extern INT16U wOPVAPercent;extern INT16U wTempDerateRange;extern INT16U g_syswTempDerateRange;extern INT16S gi_wGenCrossZeroPointer;extern INT32S dwInvVoltSum;/********************************************************************************* External routine prototypes                                                   *********************************************************************************/extern INT8U sbInvVoltSoftStart(INT16U wTrackVolt, INT16U wTrackVoltStep);extern void sSetLoadOnCmd(INT8U bValue);extern void sSetKpwm(INT16S wValue);extern INV_TD   *spGetInvTd(void);extern INV_TD   *spGetGenInvTd(void);extern INV_TD   *spGetInvSynTd(void);/********************************************************************************* Input variables                                                               *********************************************************************************//********************************************************************************* Output variables                                                              *********************************************************************************/INT16U g_uwInvTraceSourceChanged = false;INT16U g_uwInvTracesourcechangedCnt = 0;INT16U g_uwInvTraceSource = cLineModeJoinInByLine;/********************************************************************************* Internal variables                                                            *********************************************************************************/INT16U uwPhaseLockSourceLast;INT16S  wInvDCVoltCntlReal;INT16U  wInvDCVoltKp = 20;      //32;    //50;INT16U  wInvDCVoltKi = 128;      //1;INT16S      wInvDCVoltError ;INT16S  wDCVoltP;INT16S  wDCVoltI;INT16S  wDCVoltI_Res;INT16S  wRDCVoltCntl;INT16S      wPhaseLockStep = 8;INT16S      wPhaseLockLimit = 17;INT8U       bInvOverCurrCnt = 0;INT8U       bBusOverCnt = 0;INT8U       bBusUnderCnt = 0;INT32S  dwInvOverCurrCnt;INT16U  wBuckDuty=0;INT16U  wBuckPWMLimit=0;INT8U   bSwitchOnStatus=0;INT16U  wSwitchOnCheckCnt=0;INT8U   bSwitchOnBStatus=0;INT16U  wSwitchOnBCheckCnt=0;INT16U  fMainSwChg;INT32U  dwInvPowerMax;INT16U  wWatt100 = c15KWattMaxPower;INT16U  wVA100 = c15KVAMaxPower;INT16U  wCurr100 = c15KInvMaxCurr;INT16U  wWattRated;INT16U  wVARated;INT16U  wCurrRated;INT16S  wInvNegPowerLimit1 = -2000;INT16S  wInvNegPowerLimit2 = -1200;INT16U  wDevicePowerPercent;INT16U  wOverLoad110Cnt=0;INT16U  wOverLoad110FlagCnt=0;INT16U  wOverLoad102Cnt=0;INT16U  wOverLoad130Cnt=0;INT16U  wOverLoad200Cnt=0;INT16S    wLoadPowerWatt;INT16S    wLoadPowerWattPre=0;INT16S    wLoadPowerVA;INT16S    wLoadPowerVAPre=0;INT16S wLoadPowerWattDisplay;INT16S wLoadPowerVADisplay;INT16U  wLoadPowerPercent;INT16U wINVDCVoltOverLimit=200;    //200mVINT8U   bINVDCVoltOverCnt = 0;INT16S wInvDCVRef = 0;INT16S wInvDCCtrlEn = 1;INT8U bLowPowerflag = false;INT16U gi_uwLowConsumption3525OnCnt = 0;INT8U bLowPowerOnflag = false;INT8U bPowerLimitflag = 0;INT8U bOverLoadBypassflag = 0;      //1:OverLoad To Bypass EnINT16U wLoad110To200Cnt = 0;INT16U wLoadLessThan85Cnt = 0;INT8U bFristMoreThan100Flag = 0;INT8U bBatFristMoreThan110Flag = 0;INT16U wOverLoad110Flag = false;INT32S  g_dwInvDCVoltSum = 0;INT16S  g_wInvDCVoltAvg = 0;INT16S  g_wInvDCVoltCnt = 0;INT8U gi_ubLowConsumption3525OffFlag;INT16S  g_wOPVoltTransferRatio = 1024;INT8U ubHardProtectFlag=false;INT8U ubHardProtectCnt =0;INT8U g_ubPhaseWrongFlg = false;INT8U g_ubGenPhaseWrongFlg = false;INT16S g_wOPVoltFresh = 0;INT16S g_wOPVoltCntl = 0;INT16S g_wOPVolt = 0;INT32U  udwBypassOverLoad102Cnt=0;INT16U  uwBypassOverLoad120Cnt=0;INT16U  uwBypassOverLoad140Cnt=0;INT16U  uwBypassOverLoad200Cnt=0;INT16U  uwInvJob500msCnt=0;INT16U  uwLineLossZero5sCnt=0;//市电过零丢失5s计数INT16U  uwGenLossZero5sCnt=0;//发电机过零丢失5s计数INT16S  g_wInvVoltDcSamp=0;INT16S  g_wInvVoltDcSampBase=0;INT32S  dwPreInvVoltSum=0;/********************************************************************************* Internal routine prototypes                                                   *********************************************************************************/void sInvDCVoltCntl(INT16S wInvDCVoltRef, INT16U wVoltKp, INT16U wVoltKi);void sOverLoadProtect(void);void sSwitchOnChk(void);void sSetInvWatt(INT32S dwValue);INT32S  sdwGetInvWatt(void);INT32S  sdwGetBatWatt(void);void sSetBatWatt(INT32S dwValue);INT32S  sdwGetLowBatWatt(void);INT32U sdwBattWattCal(INT16U wInvVolt, INT16U wOPCurr);INT32U sdwInvVACal(INT16U wInvVolt, INT16U wOPCurr);INT32U  sdwGetInvVA(void);void sSetInvVA(INT32U dwValue);INT32U sdwLowInvVACal(INT16U wInvVolt, INT16U wOPCurr);INT32U  sdwGetLowInvVA(void);void sSetLowInvVA(INT32U dwValue);INT32U sdwInvPowerMAxCal(void);INT32U  sdwGetInvPowerMax(void);void sSetInvPowerMax(INT32U dwValue);INT16U swGetWatt100(void);void sSetWatt100(INT16U wVaule);INT16U swGetInvPowerPercent(void);void sSetInvPowerPercent(INT16U wValue);void PowerLimitUpdate(void);void sSavePowerChk(void);void sFrePhaseLockProc(void);void sParaShareCurChk(void);void sOPVoltTransferRatioCal(INT16U uwInverterVolt);void sKpwmUpdate(void);void sHardProtectCnt(void);void sSineLinePhaseChk(INT16U uwLinePeriodTime, INV_TD *pInvTd, INT8U ubFilter);void sLinePhaseChk(INT16U bFilter);void sGenPhaseChk(INT8U bFilter);INT16S sOutputVoltDrtProc(INT16S wOutputVoltRated);void sInvPowerFilter(INT16U wFilter);/********************************************************************************* Routines' implementations                                                     *********************************************************************************/INT16U TESTFLAGAA = 0;void sInvLoadOPTask(void)       //10ms{    TASK_EVENT  event;    sInverterModuleInit();    sLoadModuleInitial();    sSetStepHighLimit(25);    sSetPhaseLossLimit(250);    sSetPhaseOKLimit(70);    sSetPeriodOKLimit(25);    g_wOPVoltCntl = cVac220v;    while(1)    {        event=OSEventPend();        if(event&(1<<eInvLoadOPAdjustVolt))        {        }        if(event&(1<<eInvLoadOPSinZero))        {            sRInverterVoltAdj(swInvVoltRmsCal());            sRInverterVoltFilter(100);            //sParaAdjDataCal();//并机电压调节            sROPVoltAdj(swOpVoltRmsCal());            sROPVoltFilter(100);            sRInverterInvLCurrAdj(swInvLCurrRmsCal());            sROPCurrentAdj(swOPCurrRmsCal());            sOPVoltTransferRatioCal(swGetRInverterVoltNew());            sOPWattCal(sdwOPWattCal());      //OPWatt  Vop*Iop            sOPVACal(swGetROPVolt());      //OPVA            sOPPowerFilter(1000);            sOPPowerPercentMaxCal(wWatt100,wVA100,wCurr100);            sOPPowerBatPercentMaxCal(wWatt100,wVA100);            sSetInvWatt(sdwInvWattCal());       //CHARGE            sInvPowerFilter(1000);            sSetBatWatt(sdwBatWattCal());       //BatWatt            sSetInvVA(sdwInvVACal(swGetRInverterVolt(),swGetRInverterInvLCurrNew()));			sInv2RelayStsUpdate();//			            sSetLowInvVA(sdwLowInvVACal(swGetRInverterVolt(),swGetRLowOPCurrentNew()));            sInvPowerPercentMaxCal(wWatt100,wVA100,wCurr100);            sKpwmUpdate();			sSmartLoadVoltAdj(swSmartLoadVoltRmsCal());//智能负载电压计算			sSmartLoadVoltFilter(100);			sSmartLoadCurrAdj(swSmartLoadCurrRmsCal());//智能负载电流计算			sSmartLoadCurrFilter(50);			sSmartLoadWattCal(sdwSmartLoadWattCal());			sSmartLoadVACal(swGetSmartLoadVolt(),swGetSmartLoadCurr());//          sSineLinePhaseChk(swGetLinePeriodCntNew(),spGetInvTd(),10);            sLinePhaseChk(10);            sGenPhaseChk(10);            if(bLowPowerflag == false && sbInverterZeroLossChk(4) == true)            {                sLoadModuleInitial();            }            if(g_uwWorkMode == cPowerOnMode)            {				sSetInvVoltSampleBiasTemp(swInvVoltAveCal());                sSetInvCurrSampleBiasTemp(swRInvCurrAveCal());				sSetOpVoltSampleBiasTemp(swOpVoltAveCal());                sSetOpCurrSampleBiasTemp(swROpCurrAveCal());                sSetLowOpCurrSampleBiasTemp(swLowOpCurrAveCal());				sSetLineVoltSampleBiasTemp(swLineVoltAveCal());                sSetLineCurrSampleBiasTemp(swLineCurrAveCal());				sSetGenVoltSampleBiasTemp(swGenVoltAveCal());                sSetGenCurrSampleBiasTemp(swGenCurrAveCal());				sSetBatCurr1SampleBiasTemp(swBatCurr1Cal());                sSetBatCurr2SampleBiasTemp(swBatCurr2Cal());				sSetPvOutCurrSampleBiasTemp(swPvOutCurrCal());				sSetPv1CurrSampleBiasTemp(swPv1CurrCal());				sSetPv2CurrSampleBiasTemp(swPv2CurrCal());				            }			else if(g_uwWorkMode == cBatteryMode)			{				//g_wInvVoltDcSamp = ((INT32S)g_wInvVoltDcSamp*50 + (INT32S)swInvVoltAveCal()*14)>>6;				swInvVoltAveCal();				if(mOPRLYChk()==cOPOff)				{					g_wInvVoltDcSampBase = ((INT32S)g_wInvVoltDcSampBase*32 + (dwInvVoltSum/8)*32)>>6;				}				else				{					if((dwPreInvVoltSum - dwInvVoltSum)>100)					{						dwInvVoltSum = dwPreInvVoltSum - 100;					}					else if((dwPreInvVoltSum - dwInvVoltSum)<-100)					{						dwInvVoltSum = dwPreInvVoltSum + 100;					}					g_wInvVoltDcSamp = (((INT32S)g_wInvVoltDcSamp*32 + (dwInvVoltSum/8)*32)>>6)-g_wInvVoltDcSampBase*2/3;//10K机器测试结果，初始计算出来的零偏没法完全校准					dwPreInvVoltSum = dwInvVoltSum;				}			}			if(g_uwVoltBiasCalFlag == 1)			{				sSetLineVoltSampleBiasTemp(swLineVoltAveCal());				sSetGenVoltSampleBiasTemp(swGenVoltAveCal());			}            //if(sbRInverterShortChk(swGetROPCurrNew(),5))            if(sbRInverterShortChk(swGetRInverterInvLCurrNew(),5))            {                sSetFaultCode(eInvShort);				swSetInvShortFault(true);                //OSEventSend(cPrioSuper, eSuperFault);                OSEventSend(cPrioPara, eParaToFaultMode);            }			else			{				//swSetInvShortFault(false);			}            if(sbRInverterVoltHighChk(50) == true)            {                sSetFaultCode(eInvVoltFault);				swSetInvVoltHighFault(true);                OSEventSend(cPrioSuper,eSuperFault);				TESTFLAGAA |= 0x1;            }			else			{				//swSetInvVoltHighFault(false);			}            sRInverterVoltHiFanStopChk(50, 250);            sSavePowerChk();            sFrePhaseLockProc();            sParaShareCurChk();            //if(swGetFaultCode()==0)            {                if(sRInverterNegPowChk(sdwGetBatWatt(), wInvNegPowerLimit1, wInvNegPowerLimit2, 3) == true)                {                    sSetFaultCode(eInvNegPower);					swSetInvBackflowFault(true);                    OSEventSend(cPrioSuper, eSuperFault);                }				else				{					//swSetInvBackflowFault(false);				}                if(sbRInverterVoltLowChk(100) == true)                {                    sSetFaultCode(eOutUV);					swSetOutputVoltLowFault(true);                    OSEventSend(cPrioSuper,eSuperFault);                }				            }        }        if(event&(1<<eInvLoadOPInvZero))        {            sInverterFreqCal(swGetInvertPeriodNew());            sInverterZeroLossClr();            sHardProtectCnt();        }        if(event&(1<<eInvLoadOPTimer))//10ms        {            if(wIDAutoGenerateStep == cPrioInvLoadOP)            {                wIDHighTemp += EPwm1Regs.TBCTR;                wIDLowTemp += EPwm6Regs.TBCTR;                wIDAutoGenerateStep = cPrioGrid;            }			//更新SOGI系数			if(++uwInvJob500msCnt > 50)//500ms			{				uwInvJob500msCnt = 0;				Spll_SogiParaUpdate();			}			//持续5s将系数复位一次			if(swGetLineLoseZeroCnt() > 2300)			{				if(++uwLineLossZero5sCnt > 500)				{					uwLineLossZero5sCnt = 0;					Spll_LineVoltInit();				}							}			else			{				uwLineLossZero5sCnt = 0;			}			if(swGetGenLoseZeroCnt() > 2300)			{				if(++uwGenLossZero5sCnt > 500)				{					uwGenLossZero5sCnt = 0;					Spll_GenVoltInit();				}			}			else			{				uwGenLossZero5sCnt = 0;			}			            PowerLimitUpdate();            if(g_uwWorkMode == cBatteryMode)            {//                if((bLowPowerflag == true ))// || sdwGetLowInvVA()<30)//                {//                    sSetLoadPowerPercent(0);//                    sSetLoadPowerWatt(0);//                    sSetLoadPowerVA(0);//                }//                else                {                    //if((wInvWattPercent < 2) || (wInvVAPercent < 2))                    if((wInvWattPercent < 2) && (wInvVAPercent < 2))                    {                        sSetLoadPowerPercent(0);                        sSetLoadPowerWatt(0);                        sSetLoadPowerVA(0);                    }                    else                    {                        sSetLoadPowerPercent(swGetInvPowerPercent());                        sSetLoadPowerWatt(sdwGetBatWatt());                        sSetLoadPowerVA(sdwGetInvVA());//						sSetLoadPowerPercent(swGetROPPercent());//                        sSetLoadPowerWatt(sdwGetOPWatt());//                        sSetLoadPowerVA(sdwGetOPVA());                    }                }            }            else            {                //if((wOPWattPercent < 2) || (wOPVAPercent < 2))                if((wOPWattPercent < 2) && (wOPVAPercent < 2))                {                    sSetLoadPowerPercent(0);                    sSetLoadPowerWatt(0);                    sSetLoadPowerVA(0);                }                else                {                    sSetLoadPowerPercent(swGetROPPercent());                    sSetLoadPowerWatt(sdwGetOPWatt());                    sSetLoadPowerVA(sdwGetOPVA());                }            }//            if(g_uwWorkMode == cBatteryMode||mOPRLYChk()==cOPOff)//            {//                wOPWattBatPercent = 0;//                wOPVABatPercent = 0;//                wOPPowerBatPercent = 0;//            }            if(g_uwWorkMode == cPowerOnMode ||g_uwWorkMode == cStandbyMode||                  g_uwWorkMode == cShutdownMode || mOPRLYChk()==cOPOff)               //daily/2012/09/24            {                sSetLoadPowerWattPre(0) ;                sSetLoadPowerVAPre(0) ;                sSetLoadPowerWatt(0);                sSetLoadPowerVA(0);                sSetLoadPowerPercent(0);            }            sOverLoadProtect();            sSwitchOnChk();            if(g_uwInvTraceSourceChanged)//10ms一次            {                if(g_uwInvTracesourcechangedCnt>0)                {                    g_uwInvTracesourcechangedCnt --;                }                else                {                    g_uwInvTraceSourceChanged =false;                }            }        }    }}/*********************************************************Description:    Check loads status, if over load, set warning or fault codeInput:      Load percentOutput:     Load status**********************************************************/void sOverLoadProtect(void)//10ms{    static INT16U  wOverLoadRstClrCnt = 0;	//1、负载过载检测    if(swGetLoadPowerPercent()>200)    {        bFristMoreThan100Flag = 1;        if(wOverLoad200Cnt < 20000)        {            wOverLoad200Cnt++;        }        if(wOverLoad130Cnt < 20000)        {            wOverLoad130Cnt++;        }        if(wOverLoad110Cnt < 20000)        {            wOverLoad110Cnt++;        }		if(wOverLoad102Cnt < 60000)        {            wOverLoad102Cnt++;        }    }    else if(swGetLoadPowerPercent()>130)    {        bFristMoreThan100Flag = 1;        if(wOverLoad130Cnt < 20000)        {            wOverLoad130Cnt++;        }        if(wOverLoad110Cnt < 20000)        {            wOverLoad110Cnt++;        }		if(wOverLoad102Cnt < 60000)        {            wOverLoad102Cnt++;        }        if(wOverLoad200Cnt > 0)        {            wOverLoad200Cnt--;        }    }    else if(swGetLoadPowerPercent()>110)    {		bFristMoreThan100Flag = 1;        if(wOverLoad110Cnt < 20000)        {            wOverLoad110Cnt++;        }		if(wOverLoad102Cnt < 60000)        {            wOverLoad102Cnt++;        }        if(wOverLoad130Cnt > 0)        {            wOverLoad130Cnt--;        }        if(wOverLoad200Cnt > 0)        {            wOverLoad200Cnt--;        }    }	else if(swGetLoadPowerPercent()>102)    {        bFristMoreThan100Flag = 1;        if(wOverLoad102Cnt < 60000)        {            wOverLoad102Cnt++;        }		if(wOverLoad110Cnt > 0)        {            wOverLoad110Cnt--;        }        if(wOverLoad130Cnt > 0)        {            wOverLoad130Cnt--;        }        if(wOverLoad200Cnt > 0)        {            wOverLoad200Cnt--;        }    }    else    {//        if(bFristMoreThan100Flag == 1)//        {//            bFristMoreThan100Flag = 0;//			if(wOverLoad102Cnt > 52)//            {//                wOverLoad102Cnt = 52;//            }//            if(wOverLoad110Cnt > 52)//            {//                wOverLoad110Cnt = 52;//            }//            if(wOverLoad130Cnt > 52)//            {//                wOverLoad130Cnt = 52;//            }//            if(wOverLoad200Cnt > 4)//            {//                wOverLoad200Cnt = 4;//            }//        }//        else//        {//            if(wOverLoad110Cnt > 1050)//            {//                wOverLoad110Cnt = 1050;//            }//            if(wOverLoad130Cnt > 550)//            {//                wOverLoad130Cnt = 550;//            }//            if(wOverLoad200Cnt > 20)//            {//                wOverLoad200Cnt = 20;//            }//        }		if(wOverLoad102Cnt > 0)        {            wOverLoad102Cnt--;        }        if(wOverLoad110Cnt > 0)        {            wOverLoad110Cnt--;        }        if(wOverLoad130Cnt > 0)        {            wOverLoad130Cnt--;        }        if(wOverLoad200Cnt > 0)        {            wOverLoad200Cnt--;        }    }    if(wOverLoad110Cnt > 0)    {        wOverLoad110Flag = true;    }    else    {        wOverLoad110Flag = false;    }	//2、旁路过载检测	if((sGetLinePowerPercent()>200)||(sGetGenPowerPercent()>200))	{		if(uwBypassOverLoad200Cnt < 20000)		{			uwBypassOverLoad200Cnt++;		}		if(uwBypassOverLoad140Cnt < 20000)		{			uwBypassOverLoad140Cnt++;		}		if(uwBypassOverLoad120Cnt < 30000)		{			uwBypassOverLoad120Cnt++;		}		if(udwBypassOverLoad102Cnt < 180000)		{			udwBypassOverLoad102Cnt++;		}	}	else if((sGetLinePowerPercent()>140)||(sGetGenPowerPercent()>140))	{		if(uwBypassOverLoad140Cnt < 20000)		{			uwBypassOverLoad140Cnt++;		}		if(uwBypassOverLoad120Cnt < 30000)		{			uwBypassOverLoad120Cnt++;		}		if(udwBypassOverLoad102Cnt < 180000)		{			udwBypassOverLoad102Cnt++;		}		if(uwBypassOverLoad200Cnt > 0)		{			uwBypassOverLoad200Cnt--;		}	}	else if((sGetLinePowerPercent()>120)||(sGetGenPowerPercent()>120))	{		if(uwBypassOverLoad120Cnt < 30000)		{			uwBypassOverLoad120Cnt++;		}		if(udwBypassOverLoad102Cnt < 180000)		{			udwBypassOverLoad102Cnt++;		}		if(uwBypassOverLoad140Cnt > 0)		{			uwBypassOverLoad140Cnt--;		}		if(uwBypassOverLoad200Cnt > 0)		{			uwBypassOverLoad200Cnt--;		}	}	else if((sGetLinePowerPercent()>102)||(sGetGenPowerPercent()>102))	{		if(udwBypassOverLoad102Cnt < 180000)		{			udwBypassOverLoad102Cnt++;		}		if(uwBypassOverLoad120Cnt > 0)		{			uwBypassOverLoad120Cnt--;		}		if(uwBypassOverLoad140Cnt > 0)		{			uwBypassOverLoad140Cnt--;		}		if(uwBypassOverLoad200Cnt > 0)		{			uwBypassOverLoad200Cnt--;		}	}	else	{//		if(udwBypassOverLoad102Cnt > 52)//		{//			udwBypassOverLoad102Cnt = 52;//		}//		if(uwBypassOverLoad120Cnt > 52)//		{//			uwBypassOverLoad120Cnt = 52;//		}//		if(uwBypassOverLoad140Cnt > 52)//		{//			uwBypassOverLoad140Cnt = 52;//		}//		if(uwBypassOverLoad200Cnt > 4)//		{//			uwBypassOverLoad200Cnt = 4;//		}		if(udwBypassOverLoad102Cnt > 0)		{			udwBypassOverLoad102Cnt--;		}		if(uwBypassOverLoad120Cnt > 0)		{			uwBypassOverLoad120Cnt--;		}		if(uwBypassOverLoad140Cnt > 0)		{			uwBypassOverLoad140Cnt--;		}		if(uwBypassOverLoad200Cnt > 0)		{			uwBypassOverLoad200Cnt--;		}	}    if((g_uwWorkMode != cPowerOnMode)&&(g_uwWorkMode != cTestMode))    {		//旁路1.02倍由30分钟改为不保护        if(wOverLoad200Cnt >= 20 || wOverLoad130Cnt >= 500 || wOverLoad110Cnt >= 6000||wOverLoad102Cnt >= 60000||\			uwBypassOverLoad200Cnt >= 20 || uwBypassOverLoad140Cnt >= 1000 ||uwBypassOverLoad120Cnt >= 30000)			//uwBypassOverLoad120Cnt >= 30000 || udwBypassOverLoad102Cnt >= 180000)        {            sSetFaultCode(eLoadOverLoad);			wOverLoad102Cnt = 0;            wOverLoad130Cnt = 0;            wOverLoad110Cnt = 0;            wOverLoad200Cnt = 0;			udwBypassOverLoad102Cnt = 0;			uwBypassOverLoad120Cnt = 0;			uwBypassOverLoad140Cnt = 0;			uwBypassOverLoad200Cnt = 0;            OSEventSend(cPrioSuper, eSuperFault);			swSetOverLoadFault(true);        }        else if(wOverLoad130Cnt >= 500 || wOverLoad110Cnt > 1000)        {            //mOverLoadFail = true;        }    }    if(wOverLoad102Cnt > 50)    {        sSetWarningCode(cOverLoad);		sSetWarnCode(eOverLoadAlarm);		swSetLoadOverAlarm(true);        wOverLoad110Flag = true;    }    else    {        if(wOverLoad102Cnt < 5)        {            sClrWarningCode(cOverLoad);			//swSetOverLoadFault(false);            wOverLoad110Flag = false;			if(swGetWarnCode() == eOverLoadAlarm)			{				sSetWarnCode(0);			}			swSetLoadOverAlarm(false);            //mOverLoadFail = false;        }    }	if(udwBypassOverLoad102Cnt > 50)	{		if(g_LineModeJoinInWay == cLineModeJoinInByGen)		{			sSetWarnCode(eGenOverLoad);			swSetGenLoadOverAlarm(true);		}		else		{			sSetWarnCode(eGridOverLoad);			swSetGridLoadOverAlarm(true);		}	}	else	{		if(udwBypassOverLoad102Cnt < 5)        {			if((swGetWarnCode() == eGenOverLoad)||(swGetWarnCode() == eGridOverLoad))			{				sSetWarnCode(0);			}			swSetGenLoadOverAlarm(false);			swSetGridLoadOverAlarm(false);		}	}    if(sbGetOverLoadCnt()>0 && sbGetOverLoadCnt()<=3)//这个地方也会恢复    {        if((sdwGetWarningCode() & cOverLoad) != cOverLoad)        {            wOverLoadRstClrCnt++;            if(wOverLoadRstClrCnt>60000)//20Min clear overload cnt            {                wOverLoadRstClrCnt = 0;                sSetOverLoadCnt(0);            }        }        else        {            wOverLoadRstClrCnt = 0;        }    }}void sSwitchOnChk(void){    if(!swGetComDSPToMCUAlarm() && (!swGetRemoteOnFlg()) && bSwitchOnStatus == false)    {        if(hiSWOn == 0)        {            wSwitchOnCheckCnt ++;            if(wSwitchOnCheckCnt >= 25) //0.5s            {                wSwitchOnCheckCnt = 0;                bSwitchOnStatus = true;                sSetLoadOnCmd(1);                //sSetKeyCode(cInvOnKeyPressBit);                if(swGetEepromBeepCtrlStatus() == cEnable )                {                    fMainSwChg=1;                }            }        }        else        {            wSwitchOnCheckCnt = 0;        }    }    else    {        if(hiSWOn == 1)        {            wSwitchOnCheckCnt ++;            if(wSwitchOnCheckCnt >= 25) //0.5s            {                wSwitchOnCheckCnt = 0;                bSwitchOnStatus = false;                sSetLoadOnCmd(0);                if(swGetEepromBeepCtrlStatus() == cEnable )                {                    fMainSwChg=1;                }            }        }        else        {            wSwitchOnCheckCnt = 0;			//if((swGetComDSPToMCUAlarm()&&(swGetWorkMode() == cStandbyMode))||swGetRemoteOnFlg())			if(swGetComDSPToMCUAlarm()||swGetRemoteOnFlg())            {                sSetLoadOnCmd(0);                bSwitchOnStatus = false;			}        }    }}INT32U sdwBattWattCal(INT16U wInvVolt, INT16U wOPCurr){    INT32U dwInvVATemp;    dwInvVATemp = (INT32U)wInvVolt * wOPCurr / 100;    return(dwInvVATemp);}INT32U sdwInvVACal(INT16U wInvVolt, INT16U wOPCurr){    INT32U dwInvVATemp;    dwInvVATemp = (INT32U)wInvVolt * wOPCurr / 100;    return(dwInvVATemp);}INT32U sdwLowInvVACal(INT16U wInvVolt, INT16U wOPCurr){    INT32U dwLowInvVATemp;    dwLowInvVATemp = (INT32U)wInvVolt * wOPCurr / 1000;    return(dwLowInvVATemp);}INT32U sdwInvPowerMAxCal(void){    INT32U  dwInvWattTemp;    dwInvWattTemp = abs(dwInvWatt);    if(dwInvWattTemp >= dwInvVA)    {        return(dwInvWattTemp);    }    else    {        return(dwInvVA);    }}void PowerLimitUpdate(void){    if(g_uwWorkMode == cLineMode ||g_uwWorkMode == cBypassMode)    {        if(swGetRLineVoltNew()>= cVac90v && swGetRLineVoltNew() < cVac170v)        {            wVA100 = wVARated - (INT16U)((INT32U)wVARated * (cVac170v - swGetRLineVoltNew()) / 1600);            wWatt100 = wWattRated - (INT16U)((INT32U)wWattRated * (cVac170v - swGetRLineVoltNew()) / 1600);            bPowerLimitflag = 1;//			sSetWarnCode(eHSOTDeAlarm);//			swSetSinkTempOverDerateAlarm(true);        }        else        {            wWatt100 = wWattRated;            wVA100 = wVARated;            bPowerLimitflag = 0;			if(swGetWarnCode() == eHSOTDeAlarm)			{				sSetWarnCode(0);			}//			swSetSinkTempOverDerateAlarm(false);        }		wCurr100 = wCurrRated;    }    else if(g_uwWorkMode == cBatteryMode)    {//      if((1 == sbGetTxtOverTempDerate()) || (1 == sbGetInvOverTempDerate()))//      {//          if(1200 == swGetEepromOutputVolt())//          {//              wWatt100 = (INT16U)(((INT32U)wWattRated * (INT32U)846) >> 10);//              wVA100 = (INT16U)(((INT32U)wVARated * (INT32U)846) >> 10);//          }//          else//          {//              wWatt100 = (INT16U)(((INT32U)wWattRated * (INT32U)774) >> 10);//              wVA100 = (INT16U)(((INT32U)wVARated * (INT32U)774) >> 10);//          }//      }//      else        {            wWatt100 = wWattRated;            wVA100 = wVARated;        }        bPowerLimitflag = 0;		if(swGetWarnCode() == eHSOTDeAlarm)		{			sSetWarnCode(0);		}		wCurr100 = wCurrRated;		//swSetSinkTempOverDerateAlarm(false);    }    else    {        wWatt100 = wWattRated;        wVA100 = wVARated;        bPowerLimitflag = 0;		if(swGetWarnCode() == eHSOTDeAlarm)		{			sSetWarnCode(0);		}		wCurr100 = wCurrRated;		//swSetSinkTempOverDerateAlarm(false);    }}INT16S flag000000;INT16U PhaseLockState = 0;extern INT16U      wInverterPeriodCntNew;void sFrePhaseLockProc(void){    INT16S wTemp;    INT16U wInvPeriodLast;    if((wParaMode != cMasterMode && liHOSTRXD == 0))//&&hoInv1Relay != 1)    {        PhaseLockState = 1;        wInvPeriodLast = swGetSinePeriodCntNew();        sInverterPhaseLock(swGetSinePeriodCntNew(),spGetInvSynTd(),swGetSynPeriodCntNew(),swGetPhaseLockStep());        sPeriodLimit(swGetPhaseLockLimit(),wInvPeriodLast);		if(sbGetLineVoltLossStatus() == false && sbGetLineFreqLossStatus() == false        && wParaLineAbnormalFlg != 2 && ((g_uwWorkMode != cLineMode)||\        (g_uwWorkMode == cLineMode && g_LineModeJoinInWay == cLineModeJoinInByLine)))		{			g_uwInvTraceSource = cLineModeJoinInByLine;		}		else if(sbGetGenVoltLossStatus() == false && sbGetGenFreqLossStatus() == false   //Gen Phase Lock        && wParaLineAbnormalFlg != 2 && sbGetEepromGenInputEn()&&!sbGetEepromSmartLoadEn())		{			g_uwInvTraceSource = cLineModeJoinInByGen;		}    }    else if(sbGetLineVoltLossStatus() == false && sbGetLineFreqLossStatus() == false        && wParaLineAbnormalFlg != 2 && ((g_uwWorkMode != cLineMode)||(g_uwWorkMode == cLineMode && g_LineModeJoinInWay == cLineModeJoinInByLine)))//if((sdwGetWarningCode() & cLineLoss) == 0)      //Grid phase lock    {        PhaseLockState = 2;        wInvPeriodLast = swGetSinePeriodCntNew();        sInverterPhaseLock(swGetSinePeriodCntNew(),spGetInvTd(),swGetLinePeriodCntNew(),swGetPhaseLockStep());        sPeriodLimit(swGetPhaseLockLimit(),wInvPeriodLast);        g_uwInvTraceSource = cLineModeJoinInByLine;    }    else if(sbGetGenVoltLossStatus() == false && sbGetGenFreqLossStatus() == false   //Gen Phase Lock        && wParaLineAbnormalFlg != 2 && sbGetEepromGenInputEn()&&!sbGetEepromSmartLoadEn())    {        PhaseLockState = 3;        wInvPeriodLast = swGetSinePeriodCntNew();        sInverterPhaseLock(swGetSinePeriodCntNew(),spGetGenInvTd(),swGetGenPeriodCntNew(),swGetPhaseLockStep());        sPeriodLimit(swGetPhaseLockLimit(),wInvPeriodLast);        g_uwInvTraceSource = cLineModeJoinInByGen;    }    else    {        PhaseLockState = 4;        sFreeRun();    }    wTemp=swInverterStepCal(50,wRCountsPerPeriod);//wRCountsPerPeriod=384    sSetInvStep(wTemp);//	  wTemp=swInverterStepCal(50,wRCountsPerPeriod);//wRCountsPerPeriod=384//	  sSetInvStep(cINV_PWM_PERIOD);    //跟踪源改变，需要额外500ms以判定锁相是否完成    if(g_uwWorkMode == cBatteryMode)    {        if(uwPhaseLockSourceLast != g_uwInvTraceSource)        {            g_uwInvTraceSourceChanged =  true;            g_uwInvTracesourcechangedCnt = 50;        }    }    else    {        g_uwInvTraceSourceChanged = false;        g_uwInvTracesourcechangedCnt = 0;    }    uwPhaseLockSourceLast= g_uwInvTraceSource;	//放在电池模式处理    flag000000 = 3;    if((sbGetInverterPLStatus()== true && g_uwInvTraceSourceChanged == false)&&        ((sbGetPalLineLossStatus() == false &&g_uwInvTraceSource == cLineModeJoinInByLine)//市电正常且跟踪市电锁相        ||(sbGetPalGenLossStatus() == false && g_uwInvTraceSource == cLineModeJoinInByGen)))    {        //判定接入市电还是发电机----------//        flag000000 = 4;        if((sbGetPalLineLossStatus() == false && g_uwInvTraceSource == cLineModeJoinInByLine))        {            flag000000 = 1;            g_LineModeJoinInWay = cLineModeJoinInByLine;//相当于一个标志        }        else if(sbGetPalGenLossStatus() == false && g_uwInvTraceSource == cLineModeJoinInByGen)        {            flag000000 = 2;            g_LineModeJoinInWay = cLineModeJoinInByGen;        }        flag000000 = flag000000 + 3;    }}void    sParaShareCurChk(void){//    static INT16U s_uwShareCurrChkCnt = 0;//    //if (swGetFBControlStatus() == cFBInverterControl && hoInv1Relay == 1 && (swGetEepromOutputMode() >= cOP_Parallel))//    if(swGetFBControlStatus() == cFBInverterControl && (swGetEepromOutputMode() >= cOP_Parallel))//    {//        //share current >= 5A//        if(swGetOPShareCurr() >= cIac5A)//        {//            if(swGetOPShareCurr() > (swGetROPCurrNew() * 5))//            {//                s_uwShareCurrChkCnt ++;//                if(s_uwShareCurrChkCnt >= 10)//                {//                    s_uwShareCurrChkCnt = 0;//                    sSetFaultCode(eOPCircuitFault);//                    //OSEventSend(cPrioPara, eParaToFaultMode);//                    OSEventSend(cPrioSuper, eSuperFault);//                }//            }//            else//            {//                s_uwShareCurrChkCnt = 0;//            }//        }//        //share current < 5A//        else//        {//            if (swGetOPShareCurr() > (swGetROPCurrNew() + cIac4A))//            {//                s_uwShareCurrChkCnt ++;//                if (s_uwShareCurrChkCnt >= 10)//                {//                    s_uwShareCurrChkCnt = 0;//                    sSetFaultCode(eOPCircuitFault);//                    //OSEventSend(cPrioPara, eParaToFaultMode);//                    OSEventSend(cPrioSuper, eSuperFault);//                }//            }//            else//            {//                s_uwShareCurrChkCnt = 0;//            }//        }//    }//    else//    {//        s_uwShareCurrChkCnt = 0;//    }}void sSavePowerChk(void){//  static INT16U wCnt = 0;    //static INT16U wCnt1 = 0;    INT16U wTemp = 0;    if(g_uwWorkMode == cBatteryMode )    {//      if((abs(sdwGetLowBatWatt())<= 5)&&(bLowPowerflag ==false))//if below 5W//      {//          if(++wCnt > 250)                             //5s//          {//              wCnt = 0;//              bLowPowerflag = true;//          }//      }//      else if((abs(sdwGetLowBatWatt()) > 10)) //if over 10W or 0.1A ||(swGetRLowOPCurrentNew() >10)//      {//          wCnt = 0;//          bLowPowerflag = false;////          if(ho3525ON == 0)//          {//              ho3525ONOn;//          }//          if(swGetFBControlStatus() != cFBInverterControl && wSwitchToLineEn ==false)//          {//              sSetFBControlStatus(cFBInverterControl );//          }//      }//      else//      {//          wCnt = 0;//      }        if(sbGetInvVoltSoftFinishSts() != true)        {            sSetInvVoltSoftFinishSts(sbInvVoltSoftStart(swGetEepromOutputVolt()/10,5));        }        else        {            if(bLowPowerflag == false || swGetEepromOutputMode() != cOP_Single)            {                if(swGetFBControlStatus() != cFBInverterControl && wSwitchToLineEn ==false && (!g_uwPowerSaveModeFlag))                {                    sSetFBControlStatus(cFBInverterControl );                }                wTemp =sOutputVoltDrtProc(swGetEepromOutputVolt());                if(swGetInvDCCtrlEn() == true)                {                    sRVoltRegu(wTemp,2,1);      //2300                }            }            else            {                if(swGetInvDCCtrlEn() == true)                {                    sRVoltRegu(swGetEepromOutputVolt(),3,1);                }                if(swGetFBControlStatus() != cFBInverterControl && wSwitchToLineEn ==false && (!g_uwPowerSaveModeFlag) )                {                    sSetFBControlStatus(cFBInverterControl );                }            }        }    }    else if(g_uwWorkMode == cStandbyMode )    {        if(wFBControlStatus != cFBInverterControl)        {//          wCnt1 = 0;            bLowPowerflag = false;            sSetInvVoltSoftFinishSts(false);            sSetRSinAmp(3500);//最低启动电压            sSetRNewSinAmp(3500);			sSetRNewSinAmpTemp(3500);        }    }    else    {//      wCnt = 0;        //wCnt1 = 0;        bLowPowerflag = false;        sSetInvVoltSoftFinishSts(false);        sSetRSinAmp(3500);        sSetRNewSinAmp(3500);		sSetRNewSinAmpTemp(3500);    }}void sOPVoltTransferRatioCal(INT16U uwInverterVolt){    static INT16U s_uwInvVoltAvgCnt = 0;    static INT16U s_uwInvVoltAvg = 0;    INT16S wOPVoltRatio;    if((g_uwWorkMode == cBatteryMode || g_uwWorkMode == cLineMode) && sbGetInvVoltSoftFinishSts())    {        s_uwInvVoltAvg += uwInverterVolt;        if(++s_uwInvVoltAvgCnt > 5)        {            s_uwInvVoltAvg = s_uwInvVoltAvg / s_uwInvVoltAvgCnt;            if(s_uwInvVoltAvg < 500)            {                s_uwInvVoltAvg = 500;            }            wOPVoltRatio = (INT16S)(((INT32S)swGetEepromOutputVolt() << 10) / s_uwInvVoltAvg);            wOPVoltRatio = (INT16S)(((INT32S)swGetEepromOutputVolt() * wOPVoltRatio) / s_uwInvVoltAvg);            g_wOPVoltTransferRatio = (wOPVoltRatio + g_wOPVoltTransferRatio) >> 1;            s_uwInvVoltAvg = 0;            s_uwInvVoltAvgCnt = 0;        }    }    else    {        g_wOPVoltTransferRatio = 1024;        s_uwInvVoltAvg = 0;        s_uwInvVoltAvgCnt = 0;    }}void    sKpwmUpdate(void){    INT16S  wBusTemp;    INT16S  wKpwmTemp;    wBusTemp = (INT16S)(((INT32S)swGetBatAvgVoltNew() * wTxRatio)>>8);    if(wBusTemp < 250)    {        wBusTemp = 250;    }    wKpwmTemp =  (INT16S)(((INT32S)wPwmPeriod << 7) * 10 /wBusTemp);    if(wKpwmTemp > 1200)        //250v    {        wKpwmTemp = 1200;    }    else if(wKpwmTemp < 600)    //500v    {        wKpwmTemp = 600;    }    sSetKpwm(wKpwmTemp);}void sHardProtectCnt(void){    static INT8U ubCntReducedelay =0;    if(g_uwWorkMode == cBatteryMode)    {        if(ubHardProtectFlag==true)        {            ubHardProtectCnt++;            ubHardProtectFlag=false;        }        else if(ubHardProtectCnt > 0)        {            if(++ubCntReducedelay>2)            {                ubHardProtectCnt--;                ubCntReducedelay =0;            }        }    }    else    {        ubHardProtectFlag =0;        ubHardProtectCnt =0;    }}//void sSineLinePhaseChk(INT16U uwLinePeriodTime, INV_TD *pInvTd, INT8U ubFilter)//{//  INT16S uwPhaseDeltaTime;//  INT16U uwPhaseDeltaRange;//  INT16S uwLineDeltaTime;//  static INT8U s_ubLineChkCnt = 0;//  uwLineDeltaTime =pInvTd->InvTd;//  if(swGetEepromOutputMode()  == cOP_3P2)//  {//      uwPhaseDeltaTime = (INT16U)((INT32U)uwLinePeriodTime * 2 / 3);//  }//  else if(swGetEepromOutputMode()  == cOP_3P3)//  {//      uwPhaseDeltaTime = uwLinePeriodTime / 3;//  }//  else if(swGetEepromOutputMode()  == cOP_2P2)//  {//      uwPhaseDeltaTime = uwLinePeriodTime /2;//  }//  else//  {//      s_ubLineChkCnt = 0;//      g_ubPhaseWrongFlg = false;//      fLine.PhaseLoss =0;//      return;//  }////  uwPhaseDeltaRange = uwLinePeriodTime / 12;//30 degree//  uwPhaseDeltaTime =uwLineDeltaTime -uwPhaseDeltaTime;////  if(sbGetRLineVoltLoss() == true || sbGetRLineFreqLoss() == true//      ||wParaLineAbnormalFlg == 2)//  {//      s_ubLineChkCnt = 0;//      g_ubPhaseWrongFlg = false;//      fLine.PhaseLoss =0;//  }//  else if(g_ubPhaseWrongFlg)//  {//      if(abs(uwPhaseDeltaTime) < uwPhaseDeltaRange)//      {//          if(++s_ubLineChkCnt > ubFilter)//          {//              s_ubLineChkCnt = 0;//              g_ubPhaseWrongFlg = false;//              fLine.PhaseLoss =0;//          }//      }//      else//      {//          s_ubLineChkCnt = 0;//      }//  }//  else//  {//      if(abs(uwPhaseDeltaTime) > (uwPhaseDeltaRange + 100))//      {//          if(++s_ubLineChkCnt > ubFilter)//          {//              s_ubLineChkCnt = 0;//              g_ubPhaseWrongFlg = true;//              fLine.PhaseLoss =1;//          }//      }//      else//      {//          s_ubLineChkCnt = 0;//      }//  }//}void    sLinePhaseChk(INT16U bFilter){    INT16S uwPhaseDeltaTime;    INT16S uwPhaseDeltaRange;	static INT16U s_ubLineChkCnt = 0;    //    if(swGetEepromOutputMode() == cOP_3P2 || swGetEepromOutputMode() == cOP_3P3\//        || swGetEepromOutputMode() == cOP_2P2)    if((swGetEepromOutputMode() == cOP_3P2 || swGetEepromOutputMode() == cOP_3P3\        || swGetEepromOutputMode() == cOP_2P2)||(wParaMode == cSlaveMode))    {        if(gi_wLineCrossZeroPointer >= gi_wPLLPointThreeSix)        {            uwPhaseDeltaTime = gi_wPLLPointerMax - gi_wLineCrossZeroPointer;        }        else        {            uwPhaseDeltaTime = gi_wLineCrossZeroPointer;        }    }    else    {        s_ubLineChkCnt = 0;        g_ubPhaseWrongFlg = false;        fLine.PhaseLoss =0;        return;    }		if(sbGetEepromModeSelect() == 0)//APL	{    	uwPhaseDeltaRange = gi_wPLLPointerMax /12;//30 degree	}	else	{		if(g_uwWorkMode == cLineMode)		{			uwPhaseDeltaRange = gi_wPLLPointerMax /12;//30 degree		}		else		{			uwPhaseDeltaRange = gi_wPLLPointerMax /45;//8 degree		}	}    if(sbGetRLineVoltLoss() == true || sbGetRLineFreqLossStatus() == true)    {        s_ubLineChkCnt = 0;        fLine.PhaseLoss = 0;        g_ubPhaseWrongFlg = false;    }    else if(g_ubPhaseWrongFlg)    {        if(abs(uwPhaseDeltaTime) < uwPhaseDeltaRange)        {            if(++s_ubLineChkCnt > bFilter)            {                s_ubLineChkCnt = 0;                g_ubPhaseWrongFlg = false;            }        }        else        {            s_ubLineChkCnt = 0;        }    }    else    {        if(abs(uwPhaseDeltaTime) > (uwPhaseDeltaRange + 2))        {            if(++s_ubLineChkCnt > bFilter)            {                s_ubLineChkCnt = 0;                g_ubPhaseWrongFlg = true;            }        }        else        {            s_ubLineChkCnt = 0;        }    }    if(g_uwWorkMode == cBypassMode || g_uwWorkMode == cLineMode)    {        fLine.PhaseLoss = 0;    }    else    {        fLine.PhaseLoss = g_ubPhaseWrongFlg;    }}void sGenPhaseChk(INT8U bFilter){    INT16S uwPhaseDeltaTime;    INT16S uwPhaseDeltaRange;    static INT16U s_ubChkCnt = 0;    if((swGetEepromOutputMode() == cOP_3P2 || swGetEepromOutputMode() == cOP_3P3\        || swGetEepromOutputMode() == cOP_2P2)||(wParaMode == cSlaveMode))    {        if(gi_wGenCrossZeroPointer >= gi_wPLLPointThreeSix)        {            uwPhaseDeltaTime = gi_wPLLPointerMax - gi_wGenCrossZeroPointer;        }        else        {            uwPhaseDeltaTime = gi_wGenCrossZeroPointer;        }    }    else    {        s_ubChkCnt = 0;        g_ubGenPhaseWrongFlg = false;        fGen.PhaseLoss =0;        return;    }	uwPhaseDeltaRange = gi_wPLLPointerMax /12;//30 degree    if(sbGetGenVoltLoss() == true || sbGetGenFreqLossStatus() == true)    {        s_ubChkCnt = 0;        fGen.PhaseLoss = 0;        g_ubGenPhaseWrongFlg = false;    }    else if(g_ubGenPhaseWrongFlg)    {        if(abs(uwPhaseDeltaTime) < uwPhaseDeltaRange)        {            if(++s_ubChkCnt > bFilter)            {                s_ubChkCnt = 0;                g_ubGenPhaseWrongFlg = false;            }        }        else        {            s_ubChkCnt = 0;        }    }    else    {        if(abs(uwPhaseDeltaTime) > (uwPhaseDeltaRange + 5))        {            if(++s_ubChkCnt > bFilter)            {                s_ubChkCnt = 0;                g_ubGenPhaseWrongFlg = true;            }        }        else        {            s_ubChkCnt = 0;        }    }    if(g_uwWorkMode == cBypassMode || g_uwWorkMode == cLineMode)    {        fGen.PhaseLoss = 0;    }    else    {        fGen.PhaseLoss = g_ubGenPhaseWrongFlg;    }}INT16S sOutputVoltDrtProc(INT16S wOutputVoltRated){    static INT8U s_uwTempDeratCnt =0;    static INT16S s_wTempDerateRange =0;    INT16S wTempDerateT;    if(g_wOPVoltFresh)    {        if(g_wOPVolt != g_wOPVoltCntl)        {            g_wOPVolt = g_wOPVoltCntl;        }    }    if(wParaMode == cMasterMode)    {        if(g_uwWorkMode == cBatteryMode)        {            if(g_wOPVoltFresh)            {                if(++s_uwTempDeratCnt >= 8)                {                    g_wOPVoltFresh = 0;                    s_uwTempDeratCnt =0;//                  if((1 == sbGetTxtOverTempDerate()) || (1 == sbGetInvOverTempDerate()))//                  {//                      g_wOPVoltCntl -= 10;//                  }//                  else//                  {//                      g_wOPVoltCntl += 10;//                  }                    if(g_syswTempDerateRange>wTempDerateRange)                    {                        wTempDerateT= g_syswTempDerateRange;                    }                    else                    {                        wTempDerateT= wTempDerateRange;                    }                    if(s_wTempDerateRange >wTempDerateT)                    {                        s_wTempDerateRange--;                    }                    else if(s_wTempDerateRange <wTempDerateT)                    {                        s_wTempDerateRange++;                    }//                  g_wOPVoltCntl=wOutputVoltRated -(s_wTempDerateRange*cVac1v);                    if(g_wOPVoltCntl<(wOutputVoltRated -(s_wTempDerateRange*cVac1v)))                    {                        g_wOPVoltCntl+=10;                    }                    else                    {                        g_wOPVoltCntl-=10;                    }                    if(g_wOPVoltCntl > wOutputVoltRated)                    {                        g_wOPVoltCntl = wOutputVoltRated;                    }//                    else if((g_wOPVoltCntl + 300) < wOutputVoltRated)// 限制在200-230V//                    {//                        g_wOPVoltCntl = wOutputVoltRated - 300;//                    }					else if(g_wOPVoltCntl < 2000)// 限制在200V以上                    {                        g_wOPVoltCntl = 2000;                    }                }            }        }        else        {            g_wOPVoltFresh = 0;            s_uwTempDeratCnt = 0;            if(g_wOPVoltCntl != wOutputVoltRated)            {                g_wOPVoltCntl = wOutputVoltRated;            }        }    }    else    {        s_uwTempDeratCnt = 0;        g_wOPVoltFresh = 0;        //g_wOPVoltFresh = 1;    }    return(g_wOPVolt);}void sInvPowerFilter(INT16U wFilter){    if(labs(dwInvWatt-dwInvWattFilt) > (INT32S)wFilter)    {        dwInvWattFilt = dwInvWatt;    }    else    {        dwInvWattFilt = (dwInvWatt + dwInvWattFilt * 3) >> 2;    }}/********************************************************************************* Output interface Routines                                                     *********************************************************************************/INT16U swGetInvDCVoltKp(void){    return(wInvDCVoltKp);}INT16U swGetInvDCVoltKi(void){    return(wInvDCVoltKi);}INT16S  swGetPhaseLockLimit(void){    return(wPhaseLockLimit);}INT16S swGetBuckDuty(void){    return(wBuckDuty);}INT32S  sdwGetInvWatt(void){    return(dwInvWatt);}INT32S  sdwGetInvWattFilt(void){    return(dwInvWattFilt);}INT32S  sdwGetBatWatt(void){    return(dwBatWatt);}INT32S  sdwGetLowBatWatt(void){    return(dwLowBatWatt);}INT16S  swGetPhaseLockStep(void){    return(wPhaseLockStep);}INT8U sbGetInvOverCurrCnt(void){    return(bInvOverCurrCnt);}INT8U sbGetBusOverCnt(void){    return(bBusOverCnt);}INT8U sbGetBusUnderCnt(void){    return(bBusUnderCnt);}INT32U  sdwGetInvVA(void){    return(dwInvVA);}INT32U  sdwGetLowInvVA(void){    return(dwLowInvVA);}INT32U  sdwGetInvPowerMax(void){    return(dwInvPowerMax);}INT16U swGetWatt100(void){    return(wWatt100);}INT16U swGetInvPowerPercent(void){    return(wInvPowerPercent);}INT16U swGetLoadPowerPercent(void){    return(wLoadPowerPercent);}INT16S swGetLoadPowerWatt(void){    return(wLoadPowerWatt);}INT16S swGetLoadPowerWattPre(void){    return(wLoadPowerWattPre);}INT16S swGetLoadPowerWattDisplay(void){    return(wLoadPowerWattDisplay);}INT16S swGetLoadPowerVADisplay(void){    return(wLoadPowerVADisplay);}INT16S swGetLoadPowerVA(void){    return(wLoadPowerVA);}INT16S swGetLoadPowerVAPre(void){    return(wLoadPowerVAPre);}INT16S swGetInvDCVoltError(void){    return(wInvDCVoltError);}INT16S swGetDCVoltP(void){    return(wDCVoltP);}INT16S swGetDCVoltI(void){    return(wDCVoltI);}INT16S swGetDCVoltI_Res(void){    return(wDCVoltI_Res);}INT16S swGetDCVoltCntl(void){    return(wRDCVoltCntl);}INT16S swGetInvDCVRef(void){    return(wInvDCVRef);}INT16S swGetInvDCCtrlEn(void){    return(wInvDCCtrlEn);}/********************************************************************************* Input interface Routines                                                      *********************************************************************************/void sSetInvDC